'use strict';
(() => {
const KEY='gifty-direction-a-prototype-v1';
const legacyProducts=[
{id:'speaker',name:'Speaker portatile',price:8000,image:'speaker-scene.png',tag:'Musica',description:'Musica in casa, sul terrazzo e nei vostri prossimi weekend'},
{id:'lamp',name:'Lampada da tavolo',price:6000,image:'lamp-scene.png',tag:'Casa',description:'Lampada da tavolo con base verde e luce calda'},
{id:'bag',name:'Zaino da città',price:15000,image:'bag-scene.png',tag:'Viaggi',description:'Zaino verde per tutti i giorni'},
{id:'mini',name:'Mini speaker Bluetooth A106',price:3000,image:'PRD-011.webp',tag:'Musica',description:'Speaker Bluetooth compatto'},
{id:'cube',name:'Lampada cubo specchio 4D',price:7500,image:'PRD-016.webp',tag:'Casa',description:'Un gioco di luce per il suo angolo preferito'},
{id:'saturn',name:'Lampada Saturno levitante',price:12000,image:'PRD-015.webp',tag:'Casa',description:'Una piccola orbita da tenere sulla scrivania'}];
const catalogSource=window.giftyCatalog||{products:[],error:true};
const products=catalogSource.products;
const allProductIds=new Set([...products,...legacyProducts].map(p=>p.id));
const validSavedProductId=id=>typeof id==='string'&&(allProductIds.has(id)||/^PRD-\d{3}$/.test(id));
let catalogRecipient='',catalogAge='',catalogBand='',catalogType='',catalogVisible=24,pendingCatalogGift=null;
const sampleNames=['Alessandra','Beatrice','Giorgio','Federica','Davide','Luca','Martina','Sofia'];
function fresh(mode){return {mode,organiserName:'',organiserUid:null,draftId:crypto.randomUUID(),recipient:'',occasion:'Compleanno',date:'',expected:mode==='A'?8:10,quota:1000,gift:null,published:false,organiserAccount:false,participantAccount:false,participantName:'',joined:false,members:[],invitations:[],deliveryAt:null,recipientChoice:null,purchasedAt:null,actualCost:null,cardMessage:'',dedication:'',newsletter:false};}
let state={version:1,scenario:'A',role:'organiser',scenarios:{A:fresh('A'),B:fresh('B')}};
function validState(candidate){
 if(!candidate||candidate.version!==1||!['A','B'].includes(candidate.scenario)||!['organiser','participant','recipient'].includes(candidate.role))return false;
 return ['A','B'].every(key=>{const v=candidate.scenarios?.[key];return v&&['A','B'].includes(v.mode)&&typeof v.recipient==='string'&&v.recipient.length<=40&&Number.isSafeInteger(v.quota)&&v.quota>0&&Number.isSafeInteger(v.expected)&&v.expected>0&&Array.isArray(v.members)&&v.members.every(m=>typeof m.id==='string'&&typeof m.name==='string'&&Number.isSafeInteger(m.received)&&m.received>=0&&Number.isSafeInteger(m.declaration)&&m.declaration>=0)&&(!v.gift||validSavedProductId(v.gift))&&(!v.recipientChoice||validSavedProductId(v.recipientChoice))&&typeof v.cardMessage==='string'&&(!v.invitations||(Array.isArray(v.invitations)&&v.invitations.every(i=>typeof i.id==='string'&&typeof i.email==='string'&&typeof i.name==='string')));});
}
try{const stored=JSON.parse(localStorage.getItem(KEY));if(validState(stored))state=stored;}catch{}
state.favourites=Array.isArray(state.favourites)?state.favourites.filter(id=>validSavedProductId(id)):[];
Object.values(state.scenarios).forEach(v=>{v.invitations=Array.isArray(v.invitations)?v.invitations:[];v.draftId=typeof v.draftId==='string'?v.draftId:crypto.randomUUID();});
let lastGood=JSON.stringify(state);
let selectedProduct='speaker',catalogFilter='Tutti',catalogContext=state.catalogContext||(state.role==='recipient'?'recipient':'organiser'),accessContext=state.accessContext||'organiser',quotaEditing=false,paymentMethod='Satispay',catalogQuery='',finderBudget=Infinity;
const app=document.getElementById('main');
const $=s=>document.querySelector(s);
const s=()=>state.scenarios[state.scenario];
const organiser=()=>s().organiserName||'';
const money=v=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:v%100?2:0}).format((v||0)/100);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const product=id=>products.find(p=>p.id===id||p.slug===id)||legacyProducts.find(p=>p.id===id);
const gift=()=>product(s().recipientChoice||s().gift);
const received=()=>s().members.reduce((sum,m)=>sum+m.received,0);
const budget=()=>s().quota*s().members.length;
const outstanding=()=>s().members.reduce((sum,m)=>sum+Math.max(0,s().quota-m.received),0);
let authUser=null,authReady=false,authBusy=false,authMarketingDirty=false,profileMarketingDirty=false,authMode='normal',authPendingEmail='',authContext=null,authFields={firstName:'',lastName:'',email:'',privacy:false,marketing:false};
const member=()=>authUser?s().members.find(m=>m.id===authUser.uid):undefined;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));lastGood=JSON.stringify(state);return true;}catch{state=JSON.parse(lastGood);toast('Le modifiche non sono state salvate');return false;}}
function toast(text){const t=$('#toast');t.textContent=text;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,4500);}
function renderInPlace(focusSelector){const top=window.scrollY;render();window.scrollTo(0,top);if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});}
function pendingInvitations(){return s().invitations||[];}
function canManage(){return state.role==='organiser'&&!!authUser&&s().organiserUid===authUser.uid;}
function mayEditDraft(){return canManage()||(!s().published&&!s().organiserUid);}
function mayInvite(){return canManage()&&!s().deliveryAt;}
function invitationUrl(){return location.origin+'/#invite';}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
function button(text,route,kind=''){return `<a class="button ${kind}" href="#${route}">${escape(text)}</a>`;}
function action(text,name,kind='',extra=''){return `<button class="button ${kind}" data-action="${name}" ${extra}>${escape(text)}</button>`;}
function back(route='group',text='Torna al gruppo'){return `<a class="breadcrumb" href="#${route}"><span aria-hidden="true">←</span> ${escape(text)}</a>`;}
function avatars(names=s().members.map(m=>m.name),large=false){return `<div class="avatars" aria-label="${names.length} partecipanti">${names.map(name=>`<span class="avatar ${large?'large':''}" title="${escape(name)}">${escape(name.slice(0,2).toUpperCase())}</span>`).join('')}</div>`;}
function image(p){if(!p)return '<div class="product-image" aria-label="Foto non disponibile"></div>';return `<div class="product-image"><img src="${p.image.startsWith('/')?p.image:'assets/'+p.image}" alt="${escape(p.name)}" loading="lazy" decoding="async"></div>`;}
function giftBox(){return '<div class="gift-box" aria-hidden="true"><span class="gift-bow"></span></div>';}
function heading(title,subtitle='',badge=''){return `<div class="page-heading"><div><h1>${escape(title)}</h1>${subtitle?`<p class="muted">${escape(subtitle)}</p>`:''}${badge?`<span class="badge ${s().deliveryAt?'delivered':''}">${badge}</span>`:''}</div></div>`;}
function field(label,name,value,type='text',extra=''){return `<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escape(value)}" ${extra}></div>`;}
function steps(current){return `<div class="steps" aria-label="Creazione del gruppo"><span class="${current===1?'current':''}">1 · Il gruppo</span><span class="${current===2?'current':''}">2 · La quota</span><span class="${current===3?'current':''}">3 · Registrati o accedi</span></div>`;}
function icon(name,cls=''){const paths={people:'<circle cx="8" cy="7" r="3"/><circle cx="17" cy="8" r="2.5"/><path d="M2 21v-4a6 6 0 0 1 12 0v4M16 13a5 5 0 0 1 6 5v3"/>',coins:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v5c0 4 16 4 16 0V5M4 10v5c0 4 16 4 16 0M4 15v4c0 4 16 4 16 0"/>',target:'<circle cx="11" cy="13" r="9"/><circle cx="11" cy="13" r="5"/><path d="m11 13 10-10m-5 0h5v5"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h5"/>',heart:'<path d="M20.7 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-.9-1.1a5.5 5.5 0 0 0-7.8 7.8L12 22l8.7-9.5a5.5 5.5 0 0 0 0-7.8Z"/>',home:'<path d="m2 10 10-8 10 8M5 8v14h14V8M9 22v-8h6v8"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',gift:'<rect x="3" y="10" width="18" height="12" rx="1"/><path d="M2 6h20v5H2zM12 6v16M12 6C4 6 5-1 9 2c2 1 3 4 3 4Zm0 0c8 0 7-7 3-4-2 1-3 4-3 4Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 23v-3a9 9 0 0 1 18 0v3Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.gift}</svg>`;}
function groupArt(){return '<svg viewBox="0 0 100 90" class="choice-art" aria-hidden="true"><g fill="#C7DCC2"><circle cx="22" cy="28" r="10"/><path d="M6 62v-8a16 16 0 0 1 32 0v8Z"/></g><g fill="#F6D7B6"><circle cx="78" cy="29" r="9"/><path d="M64 61v-7a14 14 0 0 1 28 0v7Z"/></g><g fill="#FD8A25"><circle cx="50" cy="21" r="11"/><path d="M33 61V47a17 17 0 0 1 34 0v14Z"/></g><g fill="#005038"><circle cx="25" cy="52" r="11"/><path d="M8 87V75a17 17 0 0 1 34 0v12Z"/></g><g fill="#033922"><circle cx="72" cy="53" r="11"/><path d="M55 87V75a17 17 0 0 1 34 0v12Z"/></g></svg>';}
function giftArt(){return '<svg class="choice-art" viewBox="0 0 100 90" aria-hidden="true"><path d="M18 37h64v48H18z" fill="#033922"/><path d="M12 29h76v18H12z" fill="#00533B"/><path d="M45 29h12v56H45z" fill="#FF781D"/><path d="M51 29C24 29 28 2 40 9c9 5 11 20 11 20Zm0 0c27 0 23-27 11-20C53 14 51 29 51 29Z" fill="none" stroke="#FF781D" stroke-width="7" stroke-linecap="round"/></svg>';}
function favouriteButton(p){const selected=state.favourites.includes(p.id);return `<button class="favourite ${selected?'selected':''}" aria-pressed="${selected}" aria-label="${selected?'Rimuovi':'Aggiungi'} ${escape(p.name)} ${selected?'dai':'ai'} preferiti" data-action="favourite" data-id="${p.id}">${icon('heart')}</button>`;}

function productCards(list,context='organiser'){return `<div class="product-grid">${list.map(p=>`<article class="product-card"><div class="product-photo"><a href="#product/${p.id}" data-context="${context}">${image(p)}</a>${favouriteButton(p)}</div><div class="product-copy"><a href="#product/${p.id}" data-context="${context}"><h3>${escape(p.name)}</h3></a><div class="product-bottom"><span class="price money">${money(p.price)}</span><a class="link" href="#product/${p.id}" data-context="${context}">${context==='recipient'?'Guarda il regalo':'Scopri il regalo'}</a></div></div></article>`).join('')}</div>`;}
function home(){return `<section class="hero"><div class="hero-copy"><h1>Scegli il regalo di gruppo<br class="desktop-break"> e tieni il conto delle quote</h1><div class="hero-actions">${action('Organizza un regalo di gruppo','new-group')}<a class="link" href="#catalog">Esplora le idee regalo</a></div></div><figure class="hero-scene"><picture><source media="(max-width:760px)" srcset="assets/hero-photo-mobile.png"><img src="assets/hero-photo.png" alt="Due biglietti su un tavolo, uniti da un nastro arancio"></picture><div class="hero-card-copy"><h2>Il regalo di gruppo<br>per Mauro</h2><p>8 persone hanno aderito<br><strong>10 € a testa</strong></p>${avatars(sampleNames)}</div></figure></section><section class="home-ideas"><div class="section-heading"><h2>Idee regalo</h2><a class="link" href="#catalog">Tutte le idee</a></div>${catalogSource.error?catalogError():productCards(['PRD-011','PRD-016','PRD-038'].map(product).filter(Boolean))}</section>${window.renderGiftyHowItWorks({action})}`;}
function beginCatalogDraft(id){const p=product(id);if(!p?.url)return;state.catalogDraftGift=p.id;state.newDraft=true;state.role='organiser';if(!save())return;pendingCatalogGift=null;go('start');}
function proposeCatalogGift(){const p=product(selectedProduct);if(!p?.url)return;const v=s();if(!mayEditDraft()||!v.recipient){pendingCatalogGift=p.id;if(v.published||v.members.length||pendingInvitations().length){$('#new-group-dialog').showModal();return;}beginCatalogDraft(p.id);return;}v.gift=p.id;v.recipientChoice=null;if(v.mode==='B')v.quota=Math.ceil(p.price/((v.published&&v.members.length)?v.members.length:v.expected));if(!save())return;if(v.published){go('group');toast('Proposta salvata');}else go('setup');}
function cancelNewGroup(){pendingCatalogGift=null;$('#new-group-dialog').close();}
function confirmNewGroup(){$('#new-group-dialog').close();if(pendingCatalogGift){beginCatalogDraft(pendingCatalogGift);return;}delete state.catalogDraftGift;state.newDraft=true;state.role='organiser';if(!save())return;go('start');}
function start(){const draft=state.newDraft&&state.catalogDraftGift?{recipient:'',occasion:'Compleanno',date:'',mode:'B'}:s();return `<div class="narrow">${back('home','Torna alla home')}${steps(1)}${heading('Per chi è il regalo?')}<form id="start-form">${field('Nome festeggiato/a','recipient',draft.recipient,'text','required maxlength="40" autocomplete="off"')}<div class="field-pair"><div class="form-field"><label for="occasion">Occasione</label><select id="occasion" name="occasion">${['Compleanno','Laurea','Un nuovo inizio','Un saluto','Un’altra occasione'].map(v=>`<option ${draft.occasion===v?'selected':''}>${v}</option>`).join('')}</select></div>${field('Data celebrazione','date',draft.date,'date','required')}</div><fieldset><legend>Da dove vuoi iniziare?</legend><label class="choice"><input type="radio" name="mode" value="A" ${draft.mode==='A'?'checked':''}>${groupArt()}<span><strong>Raccolgo adesioni prima</strong></span></label><label class="choice"><input type="radio" name="mode" value="B" ${draft.mode==='B'?'checked':''}>${giftArt()}<span><strong>Scelgo il regalo prima</strong></span></label></fieldset><div class="actions"><button class="button" type="submit">Continua</button></div></form></div>`;}
function setup(){const p=gift();if(s().mode==='B'&&!p)return `<div class="narrow">${back('catalog','Torna al catalogo')}${heading('Scegli il regalo')}${button('Esplora il catalogo','catalog')}</div>`;return `<div class="narrow setup-page">${back('start','Torna al regalo')}${steps(2)}${heading(s().mode==='A'?'Quanto mettiamo a testa?':'Come dividiamo il regalo?')}<form id="setup-form" class="setup-card">${s().mode==='A'?field('Quota proposta a testa (€)','quota',(s().quota/100).toFixed(2),'number','required min="0.01" max="10000" step="0.01" class="short"'):p?`<div class="setup-product"><img src="assets/${escape(p.image)}" alt="${escape(p.name)}" width="112" height="112"><div class="setup-product-info"><h2>${escape(p.name)}</h2><strong class="setup-product-price">${money(p.price)}</strong><a class="link" href="#catalog" data-context="organiser">Cambia regalo</a></div></div>`:''}<div class="participants-field"><label for="expected">Partecipanti</label><input id="expected" name="expected" type="number" value="${s().expected}" required min="1" max="100" step="1" inputmode="numeric"></div><div class="quote-preview setup-estimate"><div><span>${s().mode==='A'?'Budget previsto':'Quota stimata'}</span><span id="estimate-note" class="small">${s().mode==='A'?`in ${s().expected} partecipanti`:`a testa in ${s().expected}`}</span></div><strong id="estimate" aria-live="polite">${s().mode==='A'?money(s().quota*s().expected):money(Math.ceil((p?.price||15000)/s().expected))}</strong></div><div class="actions"><button class="button" type="submit">Continua</button></div></form></div>`;}

function access(){if(!authReady)return `<div class="narrow auth-session-check" role="status" aria-live="polite">Verifica dell’accesso in corso</div>`;if(authUser)return account();const title=authMode==='needs-email'?'Conferma la tua email':authMode==='needs-consent'?'Completa il tuo profilo':authMode==='sent'?'Controlla la tua email':'Registrati o accedi';const disabled=authBusy||!authReady?'disabled':'';return `<div class="narrow access-page">${back(accessContext==='participant'?'invite':'setup',accessContext==='participant'?'Torna all’invito':'Torna alla quota')}${accessContext==='organiser'?steps(3):''}${heading(title)}<form id="access-form" class="panel access-card" aria-busy="${authBusy}"><fieldset class="auth-fields" ${disabled}>${authMode==='sent'?`<p>Ti abbiamo inviato un link per accedere</p><button class="button email-access" type="button" data-action="resend-email">Invia un nuovo link</button>`:authMode==='needs-email'?`<p>Inserisci l’email a cui hai ricevuto il link</p>${field('Email','email',authFields.email,'email','required maxlength="254" autocomplete="email" inputmode="email"')}<button class="button email-access" type="submit">Completa l’accesso</button>`:`${authMode==='normal'?`<button class="button google-button" type="button" data-action="google-access"><svg aria-hidden="true" viewBox="0 0 24 24" width="22" height="22"><path fill="#4285F4" d="M21.6 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.4a4.6 4.6 0 0 1-2 3v2.6h3.3c1.9-1.8 2.9-4.3 2.9-7.5Z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.7-2.4l-3.3-2.6c-.9.6-2 1-3.4 1a6 6 0 0 1-5.6-4.1H3v2.7A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.4 13.9a6 6 0 0 1 0-3.8V7.4H3a10 10 0 0 0 0 9.2l3.4-2.7Z"/><path fill="#EA4335" d="M12 6c1.5 0 2.8.5 3.8 1.5l2.9-2.9A9.7 9.7 0 0 0 12 2a10 10 0 0 0-9 5.4l3.4 2.7A6 6 0 0 1 12 6Z"/></svg>Continua con Google</button><div class="access-divider"><span>oppure con email</span></div>`:''}<div class="field-pair">${field('Nome','name',authFields.firstName,'text','required maxlength="40" autocomplete="given-name"')}${field('Cognome','surname',authFields.lastName,'text','required maxlength="60" autocomplete="family-name"')}</div>${authMode==='normal'?field('Email','email',authFields.email,'email','required maxlength="254" autocomplete="email" inputmode="email"'):''}<div class="access-consents"><label class="consent-row"><input type="checkbox" id="privacy-consent" name="privacy" required ${authFields.privacy?'checked':''}><span>Ho letto l’<a href="#privacy">informativa sulla privacy</a></span></label><label class="consent-row"><input type="checkbox" name="newsletter" ${authFields.marketing?'checked':''}><span>Voglio ricevere novità e offerte via email <small>Facoltativo</small></span></label></div><button class="button email-access" type="submit">${authMode==='needs-consent'?'Salva e continua':'Continua con email'}</button>`}</fieldset><p class="access-progress" id="access-progress" role="status" ${authReady?'hidden':''}>Verifica dell’accesso in corso</p><p class="access-error" id="access-error" role="alert" hidden></p></form></div>`;}
function readAuthFields(){const form=$('#access-form');if(!form)return;const data=new FormData(form);authFields={firstName:String(data.get('name')??authFields.firstName).trim(),lastName:String(data.get('surname')??authFields.lastName).trim(),email:String(data.get('email')??authFields.email).trim(),privacy:data.has('privacy'),marketing:data.has('newsletter')};}
function accessError(error){const code=error?.code;const messages={'auth/unauthorized-domain':'Accesso non disponibile su questo indirizzo','auth/configuration-not-found':'Accesso non disponibile su questo indirizzo','auth/operation-not-allowed':'Questo metodo di accesso non è disponibile','auth/network-request-failed':'Connessione interrotta. Riprova','auth/expired-action-code':'Il link non è più valido. Richiedine uno nuovo','auth/invalid-action-code':'Il link non è più valido. Richiedine uno nuovo','auth/email-mismatch':'Inserisci l’email a cui hai ricevuto il link','auth/profile-save-failed':'Non siamo riusciti a salvare il profilo. Riprova'};return messages[code]||'Non siamo riusciti a completare l’accesso. Riprova';}
function setAccessBusy(busy,message=''){authBusy=busy;const form=$('#access-form');if(form){form.setAttribute('aria-busy',String(busy));form.querySelector('fieldset').disabled=busy||!authReady;const progress=$('#access-progress');progress.textContent=message;progress.hidden=!message;} }
function showAccessError(error){const el=$('#access-error');if(el){el.textContent=typeof error==='string'?error:accessError(error);el.hidden=false;}else toast(accessError(error));}
function rememberAuthIntent(role=accessContext){state.authIntent={scenario:state.scenario,role,draftId:s().draftId};accessContext=role;state.accessContext=role;return save();}
function authDetails(){return {...authFields,updateMarketing:authMarketingDirty,context:authMode==='needs-consent'?authContext:state.authIntent||null};}
function applyAuthResult(result,resume=false){authUser=result?.user||null;authContext=result?.context||null;if(result?.needsEmail){authMode='needs-email';return false;}if(result?.needsConsent){authMode='needs-consent';return false;}if(!authUser)return false;if(!resume)return true;const intent=state.authIntent;if(!intent||!['A','B'].includes(intent.scenario)||!result.context){go('account');return true;}const v=state.scenarios[intent.scenario];if(v.draftId!==intent.draftId){showAccessError('Il regalo è cambiato. Torna al gruppo per continuare');return false;}if(result.context&&(result.context.scenario!==intent.scenario||result.context.role!==intent.role||result.context.draftId!==intent.draftId)){showAccessError('Il regalo è cambiato. Torna al gruppo per continuare');return false;}state.scenario=intent.scenario;if(intent.role==='participant'){if(v.deliveryAt&&!v.members.some(m=>m.id===authUser.uid)){go('closed');return true;}if(!v.members.some(m=>m.id===authUser.uid))v.members.push({id:authUser.uid,name:authUser.nome,email:authUser.email,received:0,declaration:0,invite:false});v.participantName=authUser.nome;v.participantAccount=true;v.joined=true;state.role='participant';if(v.mode==='B'&&gift())v.quota=Math.ceil((v.actualCost??gift().price)/Math.max(v.expected,v.members.length));}else{if(v.published&&v.organiserUid!==authUser.uid||v.organiserUid&&v.organiserUid!==authUser.uid){showAccessError('Questo account non può gestire il gruppo');return false;}v.organiserUid=authUser.uid;v.organiserName=authUser.nome;v.organiserAccount=true;v.published=true;state.role='organiser';}delete state.authIntent;if(!save())return false;authFields={firstName:'',lastName:'',email:'',privacy:false,marketing:false};authMarketingDirty=false;go(intent.role==='participant'?'my-quote':'share');return true;}
async function submitAccess(kind){if(authBusy||!authReady)return;readAuthFields();const error=$('#access-error');if(error)error.hidden=true;setAccessBusy(true,kind==='email'?'Invio in corso':kind==='google'?'Accesso in corso':kind==='complete'?'Verifica del link in corso':'Salvataggio in corso');try{let result;if(kind==='email'){result=await window.giftyAuth.sendEmail(authDetails());if(result?.sent){authMode='sent';render();}}else{result=kind==='google'?await window.giftyAuth.google(authDetails()):kind==='complete'?await window.giftyAuth.completeEmail(authFields.email):await window.giftyAuth.finishProfile(authDetails());if(result?.cancelled){showAccessError('Accesso annullato');return;}if(result?.redirecting)return;if(!applyAuthResult(result,true)){render();if(!result?.needsConsent&&!result?.needsEmail)showAccessError(result?.error);}}}catch(error){if(error?.code==='auth/profile-save-failed'){authMode='needs-consent';render();}showAccessError(error);}finally{setAccessBusy(false);}}
function restorePendingAccess(result){authPendingEmail=typeof result?.pendingEmail==='string'?result.pendingEmail:'';if(authPendingEmail&&!result?.user){authFields.email=authPendingEmail;if(!result.needsEmail&&!result.needsConsent)authMode='sent';}}
async function initialiseAuth(){window.giftyAuth.onChange(result=>{const previous=authUser?.uid;applyAuthResult(result,false);if(previous!==authUser?.uid){const page=(location.hash.slice(1)||'home').split('/')[0];if(!authBusy&&['account','group','members','my-quote','share'].includes(page))render();else chrome(page);}});try{const result=await window.giftyAuth.ready();authReady=true;restorePendingAccess(result);const resume=!!result?.context&&!!state.authIntent;applyAuthResult(result,resume);if(result?.needsEmail||result?.needsConsent){go('access');render();}else if(authUser&&location.hash==='#access'){go('account');render();}else if(['access','account','group','members','my-quote','share','send','purchase'].includes(location.hash.slice(1)))render();else chrome((location.hash.slice(1)||'home').split('/')[0]);}catch(error){authReady=true;if(error?.code==='auth/profile-save-failed'){authMode='needs-consent';go('access');}if(location.hash==='#access'){render();showAccessError(error);}}}

function share(){if(!canManage())return access();return `<div class="narrow">${back()}<span class="big-status" aria-hidden="true">✓</span>${heading('Il gruppo è pronto',`Il regalo di gruppo per ${s().recipient}`)}<div class="panel"><h2>Condividi il link</h2><div class="link-box"><input aria-label="Link di invito" readonly value="${escape(invitationUrl())}">${action('Copia il link','copy','small')}</div><div class="notice">${s().mode==='A'?`Ragazzi, regalo per ${escape(s().recipient)}: facciamo ${money(s().quota)} a testa. Ci state?`:`Per ${escape(s().recipient)} pensavo a questo regalo: ${escape(gift()?.name||'il regalo proposto')}. Se siamo in ${s().expected}, viene ${money(s().quota)} a testa. Ci state?`}</div><div class="actions">${button('Vai al gruppo','group')}${button('Apri l’invito','invite','secondary')}</div></div></div>`;}
function group(){if(!canManage())return state.role==='participant'?myQuote():access();const p=gift(),suggestions=products.filter(item=>item.price<=budget()).slice(0,2);return `${heading(s().recipient?`Il regalo per ${s().recipient}`:'Il tuo regalo di gruppo',s().occasion,s().deliveryAt?'Regalo consegnato':'Adesioni aperte')}<div class="group-page-actions">${!s().deliveryAt?action('Condividi il link','open-share','secondary'):''}</div><div class="workspace group-workspace"><section><div class="group-summary"><table class="budget-table"><tbody><tr><th scope="row">${icon('people')}<span>Adesioni</span></th><td>${s().members.length}</td></tr><tr><th scope="row">${icon('coins')}<label for="quota">Quota a persona</label></th><td><form id="quota-form" class="quota-inline"><div class="currency-input"><span aria-hidden="true">€</span><input id="quota" name="quota" type="number" value="${(s().quota/100).toFixed(2)}" min="0.01" max="10000" step="0.01" required aria-label="Quota a persona in euro"></div><button class="button small" type="submit">Salva</button></form></td></tr><tr><th scope="row">${icon('target')}<span>Budget previsto</span></th><td class="budget-main">${money(budget())}</td></tr><tr><th scope="row">${icon('card')}<span>Ricevuto</span></th><td>${money(received())}</td></tr><tr class="total-row"><th scope="row">Da ricevere</th><td>${money(outstanding())}</td></tr></tbody></table></div><section class="group-people" id="persone" aria-labelledby="people-title"><div class="section-heading"><h2 id="people-title">Partecipanti <span class="muted">${s().members.length}</span></h2></div>${s().members.length?`<div class="participant-list">${s().members.map((m,i)=>`<div class="member ${m.received||m.declaration?'has-payment':'pledge-only'}"><span class="avatar tone-${i%4}">${escape(m.name.slice(0,2).toUpperCase())}</span><div class="member-name"><strong>${escape(m.name)}</strong><small>${m.received>=s().quota?'Quota ricevuta':m.declaration>m.received?'Pagamento da verificare':'Ha aderito'}${m.invite?' · Può invitare':''}</small></div><span class="money">${money(m.received)} / ${money(s().quota)}</span>${m.declaration>m.received?`<button class="link" data-action="confirm" data-id="${escape(m.id)}">Conferma ${money(m.declaration-m.received)} ricevuti</button>`:''}${!s().deliveryAt?`<details class="member-options"><summary aria-label="Opzioni per ${escape(m.name)}">${icon('menu')}</summary><button class="link" data-action="delegate" data-id="${escape(m.id)}">${m.invite?'Rimuovi la delega':'Consenti di invitare'}</button></details>`:''}</div>`).join('')}</div>`:'<div class="people-empty">'+groupArt()+'<span>Nessuna adesione</span></div>'}${participantInvitations()}</section><div class="delivery"><h2>${s().deliveryAt?'Il regalo è stato consegnato':'Prepara il regalo'}</h2><div class="actions">${button('Biglietto e firme','card','secondary')}${s().deliveryAt?button('Apri la pagina del festeggiato','recipient','secondary'):p?button(`Consegna il regalo a ${s().recipient}`,'send','orange'):''}</div></div></section><aside class="stack group-recommendations">${!p&&(s().recipientChoice||s().gift)?'<p class="notice">Il regalo salvato non è nel catalogo</p>':''}${p?`<div class="panel side-product">${image(p)}<span class="eyebrow">${s().recipientChoice?'Scelto da '+escape(s().recipient):'Proposta del gruppo'}</span><h2>${escape(p.name)}</h2><p class="money">${money(p.price)}</p>${s().actualCost!==null?`<div class="summary-line"><span>Spesa registrata</span><strong>${money(s().actualCost)}</strong></div>`:''}${!s().purchasedAt?'<a class="link" href="#catalog">Cambia regalo</a>':''}${s().recipientChoice||s().purchasedAt?`<div class="actions">${button(s().purchasedAt?'Acquisto registrato':'Registra l’acquisto','purchase')}</div>`:''}</div>`:`<section class="gift-suggestions"><div class="suggestion-heading">${giftArt()}<h2>Trova il regalo per ${escape(s().recipient)}</h2><p class="muted">Budget previsto <strong>${money(budget())}</strong></p></div>${suggestions.length?productCards(suggestions):'<p class="suggestions-empty">Nessun regalo entro il budget</p>'}<a class="link catalog-link" href="#catalog">Esplora il catalogo</a></section>`}${s().deliveryAt&&!s().recipientChoice?'<div class="notice">In attesa della scelta di '+escape(s().recipient)+'</div>':''}</aside></div>`;}
function participantInvitations(){const pending=pendingInvitations();return `<div class="invitation-management"><h3>Da invitare <span class="muted">${pending.length}</span></h3>${pending.length?`<ul class="pending-list">${pending.map(inv=>`<li><span class="pending-avatar">${icon('user')}</span><div><strong>${escape(inv.name||inv.email)}</strong>${inv.name?`<span>${escape(inv.email)}</span>`:''}<small>Da invitare</small></div>${mayInvite()?`<button type="button" class="link" data-action="remove-invitation" data-id="${escape(inv.id)}" aria-label="Rimuovi ${escape(inv.email)} dalla lista">Rimuovi</button>`:''}</li>`).join('')}</ul>`:''}${mayInvite()?`<form id="invitation-form" class="invite-person-form"><div class="invite-person-fields">${field('Nome (facoltativo)','participant-name','','text','maxlength="40" autocomplete="off"')}${field('Email del partecipante','participant-email','','email','required maxlength="254" autocomplete="off"')}</div><button class="button secondary" type="submit">Aggiungi alla lista</button></form>`:'<p class="small muted">Le adesioni sono chiuse</p>'}</div>`;}
function openShare(){const dialog=$('#share-dialog');if(!dialog)return;dialog.innerHTML=`<div class="modal-heading"><h2 id="share-title">Condividi il link</h2><button type="button" class="modal-close" data-action="close-share" aria-label="Chiudi">×</button></div><p>Il regalo per ${escape(s().recipient)}</p><div class="link-box"><label class="sr-only" for="share-url">Link di invito</label><input id="share-url" readonly value="${escape(invitationUrl())}">${action('Copia il link','copy','small')}</div><p class="share-message">${s().mode==='A'?`Ragazzi, regalo per ${escape(s().recipient)}: facciamo ${money(s().quota)} a testa. Ci state?`:`Per ${escape(s().recipient)} pensavo a questo regalo: ${escape(gift()?.name||'il regalo proposto')}. Se siamo in ${s().expected}, viene ${money(s().quota)} a testa. Ci state?`}</p>`;dialog.showModal();$('#share-url').focus();}
function invite(){if(!s().published)return notFound();if(s().deliveryAt)return closed();return `<div class="narrow"><div class="invite-hero"><span class="badge">Adesioni aperte</span><h1 style="margin-top:24px">Il regalo di gruppo per ${escape(s().recipient)}</h1><p>${escape(s().occasion)} · Organizza ${escape(organiser())}</p>${gift()?image(gift()):giftBox()}${gift()?`<h2>${escape(gift().name)}</h2>`:''}${avatars()}<p>${s().members.length} persone hanno aderito</p><div class="big-quote">${money(s().quota)}</div><p class="muted">Quota proposta a testa</p><div class="actions" style="justify-content:center">${member()?button('Vai alla tua quota','my-quote'):action('Partecipa al regalo','signup-participant')}</div>${!member()?'<button class="link" data-action="decline">Non partecipo</button>':''}</div></div>`;}
function myQuote(){const m=member();if(!m)return invite();const due=s().quota-m.received;return `<div class="narrow"><span class="screen-tag"><span class="dot"></span>Il tuo gruppo</span>${heading(`La tua quota per ${s().recipient}`)}<div class="panel"><p class="muted">Da dare a ${escape(organiser())}</p><div class="quote-big">${money(Math.max(0,due))}</div>${m.received?`<p class="small">Già ricevuto: ${money(m.received)}</p>`:''}${due<0?`<p>Differenza a tuo favore: <strong>${money(-due)}</strong></p>`:''}${m.declaration>m.received?`<div class="payment-state"><strong>Pagamento dichiarato</strong><span>In attesa della conferma di ${escape(organiser())}</span></div>`:due<=0?'<div class="payment-state"><strong>Quota ricevuta</strong></div>':`<fieldset><legend>Come vuoi pagare?</legend>${['Satispay','Bonifico','Contanti'].map(v=>`<label class="choice"><input type="radio" name="paymentMethod" value="${v}" ${v===paymentMethod?'checked':''}><strong>${v}</strong></label>`).join('')}</fieldset><div class="notice" id="method-detail">${methodDetail()}</div><form id="payment-form">${field('Importo che hai dato (€)','amount',(due/100).toFixed(2),'number','required min="0.01" max="10000" step="0.01" class="short"')}<button class="button" type="submit">Ho pagato</button></form>`}<div class="summary-line"><span>Regalo</span><strong>${escape(gift()?.name||'Da scegliere insieme')}</strong></div><div class="actions">${button('Firma il biglietto','card','secondary')}${s().deliveryAt?button('Apri il regalo','recipient','secondary'):''}</div></div></div>`;}
function methodDetail(){return paymentMethod==='Bonifico'?`Chiedi l’IBAN a ${escape(organiser())} nella chat`:paymentMethod==='Contanti'?`Accordati con ${escape(organiser())} per dare la quota`:`Apri Satispay e cerca ${escape(organiser())} tra i tuoi contatti`;}
function catalogOptions(values,current,all){return `<option value="">${all}</option>`+values.map(([value,label])=>`<option value="${escape(value)}" ${value===current?'selected':''}>${escape(label)}</option>`).join('');}
function observedDate(iso){return new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));}
function catalogNotice(){if(!catalogSource.dates?.length)return '';const dates=catalogSource.dates;return `<p class="catalog-note small muted">Prezzi rilevati ${dates.length===1?'il '+observedDate(dates[0]):'dal '+observedDate(dates[0])+' al '+observedDate(dates.at(-1))}. Verifica prezzo e disponibilità su Amazon</p>`;}
function catalogError(){return `<div class="empty-state">${giftArt()}<h2>Il catalogo non è disponibile</h2><button class="button secondary" data-action="reload-catalog">Riprova</button></div>`;}
function catalog(alternatives=false){if(catalogSource.error)return `${heading('Idee regalo')}${catalogError()}`;const cap=alternatives?budget():finderBudget;const list=catalogSource.filterCatalog(products,{theme:catalogFilter,recipient:catalogRecipient,age:catalogAge,band:catalogBand,type:catalogType,query:catalogQuery,cap});const types=[...new Set(products.map(p=>p.type).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'it'));return `${back(alternatives?'recipient':s().published?'group':'home',alternatives?'Torna al regalo':s().published?'Torna al gruppo':'Torna alla home')}${heading(alternatives?'Scegli il tuo regalo':'Idee regalo',alternatives?`Fino a ${money(cap)}`:finderBudget<Infinity?`Entro ${money(finderBudget)}`:'')}<form id="catalog-search-form" class="catalog-search"><label for="query" class="sr-only">Cerca un regalo</label><input id="query" name="query" value="${escape(catalogQuery)}" maxlength="60" placeholder="Cerca un regalo"><button class="button" type="submit">Cerca</button></form><div class="catalog-toolbar" aria-label="Temi">${[['Tutti','Tutti'],...Object.entries(catalogSource.THEMES)].map(([value,label])=>`<button data-action="filter" data-value="${value}" class="${catalogFilter===value?'active':''}" aria-pressed="${catalogFilter===value}">${label}</button>`).join('')}${finderBudget<Infinity?'<button data-action="clear-finder">Rimuovi il limite di prezzo</button>':''}</div><details class="catalog-filters panel"><summary>Filtri</summary><form id="catalog-filters-form"><div class="field-pair"><div class="form-field"><label for="catalog-recipient">Per chi</label><select id="catalog-recipient" name="catalog-recipient">${catalogOptions([['uomo','Uomo'],['donna','Donna']],catalogRecipient,'Tutti')}</select></div><div class="form-field"><label for="catalog-age">Età</label><select id="catalog-age" name="catalog-age">${catalogOptions(Object.entries(catalogSource.AGES),catalogAge,'Tutte le età')}</select></div></div><div class="field-pair"><div class="form-field"><label for="catalog-band">Prezzo</label><select id="catalog-band" name="catalog-band">${catalogOptions(catalogSource.PRICE_BANDS.map(b=>[b.id,b.label]),catalogBand,'Tutti i prezzi')}</select></div><div class="form-field"><label for="catalog-type">Tipo di regalo</label><select id="catalog-type" name="catalog-type">${catalogOptions(types.map(t=>[catalogSource.categoryKey(t),t]),catalogType,'Tutti i tipi')}</select></div></div><div class="actions"><button class="button secondary" type="submit">Applica filtri</button><button class="link" type="button" data-action="clear-filters">Azzera i filtri</button></div></form></details><p class="small muted" aria-live="polite">${list.length} ${list.length===1?'idea regalo':'idee regalo'}</p>${catalogNotice()}${list.length?productCards(list.slice(0,catalogVisible),alternatives?'recipient':'organiser'):'<div class="empty-state">'+giftArt()+'<h2>Nessun regalo con questi filtri</h2><button class="link" data-action="clear-filters">Guarda tutte le idee</button></div>'}${list.length>catalogVisible?`<div class="actions"><button class="button secondary" data-action="more-products">Mostra altre idee</button><span class="small muted">${Math.min(catalogVisible,list.length)} di ${list.length}</span></div>`:''}`;}
function amazonLink(p,label='Vedi su Amazon'){return p.url?`<a class="button secondary" href="${escape(p.url)}" target="_blank" rel="sponsored nofollow noopener noreferrer">${label}</a>`:'';}
function detail(id){if(state.role==='recipient')catalogContext='recipient';const p=product(id);if(!p)return notFound();selectedProduct=id;return `${back(catalogContext==='recipient'?'alternatives':'catalog',catalogContext==='recipient'?'Torna alle alternative':'Torna alle idee regalo')}<div class="detail-grid">${image(p)}<div><p class="eyebrow">${escape(p.brand||p.tag)}</p><h1>${escape(p.name)}</h1><p>${escape(p.description)}</p><div class="detail-price"><p class="price money">${money(p.price)}</p>${favouriteButton(p)}</div>${p.observedAt?`<p class="small muted">Prezzo rilevato il ${observedDate(p.observedAt)}. Verifica prezzo e disponibilità su Amazon</p>`:''}<div class="actions">${p.url?(catalogContext==='recipient'?action('Scelgo questo regalo','choose-recipient'):action('Proponi al gruppo','propose')):''}${amazonLink(p)}</div>${!p.url?'<p class="small muted">Questo regalo è salvato nel gruppo e non è nel catalogo</p>':''}</div></div>`;}
function card(){const participant=state.role==='participant';return `<div class="narrow">${back(participant?'my-quote':s().published?'group':'home',participant?'Torna alla tua quota':s().published?'Torna al gruppo':'Torna alla home')}${heading(s().recipient?`Il biglietto per ${s().recipient}`:'Biglietto di auguri')}<div class="recipient-card"><blockquote>${escape(s().cardMessage)}</blockquote>${avatars()}<p class="small muted">Da tutto il gruppo</p>${s().dedication?`<div class="summary-line"><span>${escape(s().participantName)}</span><span>${escape(s().dedication)}</span></div>`:''}</div>${!s().deliveryAt?`<form id="card-form" style="margin-top:32px"><div class="form-field"><label for="message">${participant?'La tua dedica':'Il messaggio del gruppo'}</label><textarea id="message" name="message" maxlength="400" required>${escape(participant?s().dedication:s().cardMessage)}</textarea></div><button class="button" type="submit">${participant?'Aggiungi la tua firma':'Salva il biglietto'}</button></form>`:'<p class="notice">Il biglietto è stato consegnato</p>'}</div>`;}
function send(){if(!canManage())return access();if(s().deliveryAt)return `<div class="narrow">${back()}<span class="big-status" aria-hidden="true">✓</span>${heading('Il regalo è stato consegnato')}<div class="actions">${button('Apri il regalo','recipient')}${button('Torna al gruppo','group','secondary')}</div></div>`;if(!gift())return `<div class="narrow">${back()}${heading('Scegli prima il regalo')}${button('Trova il regalo','catalog')}</div>`;return `<div class="narrow">${back()}${heading(`Consegna il regalo a ${s().recipient}`)}<div class="panel side-product">${image(gift())}<h2>${escape(gift().name)}</h2><p>${s().members.length} partecipanti · ${escape(s().occasion)}</p><blockquote>${escape(s().cardMessage)}</blockquote>${avatars()}<div class="notice">Dopo la consegna non potranno aggiungersi altre persone</div>${action('Conferma consegna','send','orange')}<div class="actions">${button('Torna al gruppo','group','secondary')}</div></div></div>`;}
function recipient(){if(!s().deliveryAt)return `<div class="narrow"><div class="invite-hero">${giftBox()}${heading('Il regalo si sta preparando')}<p>La pagina del festeggiato si aprirà dopo la consegna</p>${button('Torna alla home','home','secondary')}</div></div>`;const p=gift();return `<section class="recipient-page"><span class="screen-tag">Dal tuo gruppo</span><h1>Un regalo per te, ${escape(s().recipient)}</h1><p>Abbiamo pensato a questo per te</p>${p?image(p):''}<h2>${escape(p?.name||'Il tuo regalo')}</h2>${s().recipientChoice?`<div class="payment-state"><strong>Hai scelto ${escape(p.name)}</strong><span>${s().purchasedAt?escape(organiser())+' ha registrato l’acquisto':escape(organiser())+' può procedere con l’acquisto'}</span></div>${!s().purchasedAt?'<a class="link" href="#alternatives">Guardo le alternative</a>':''}`:`<div class="actions">${action('Scelgo questo regalo','keep')}${button('Guardo le alternative','alternatives','secondary')}</div>`}<div class="recipient-card"><blockquote>${escape(s().cardMessage)}</blockquote>${avatars()}${s().dedication?`<p>${escape(s().dedication)}<br><span class="small muted">${escape(s().participantName)}</span></p>`:''}</div></section>`;}
function purchase(){if(!canManage())return access();const p=gift();if(!p)return notFound();return `<div class="narrow">${back()}${heading(s().purchasedAt?'Acquisto registrato':'Registra l’acquisto')}<div class="panel side-product">${image(p)}<h2>${escape(p.name)}</h2>${s().recipientChoice?`<span class="badge">Scelto da ${escape(s().recipient)}</span>`:''}${!s().purchasedAt?amazonLink(p,'Acquista su Amazon'):''}${s().purchasedAt?`<div class="summary-line"><span>Spesa registrata</span><strong>${money(s().actualCost)}</strong></div><div class="actions">${button('Torna al gruppo','group')}</div>`:`<form id="purchase-form" style="margin-top:32px">${field('Spesa effettiva (€)','actualCost',(p.price/100).toFixed(2),'number','required min="0.01" max="10000" step="0.01" class="short"')}<label class="check"><input type="checkbox" required><span>Ho completato l’acquisto</span></label><button class="button" type="submit">Registra l’acquisto</button></form>`}</div></div>`;}
function closed(){return `<div class="narrow"><div class="invite-hero">${giftBox()}${heading('Le adesioni sono chiuse')}<p>Il regalo è stato consegnato</p>${member()?button('Apri il tuo gruppo','my-quote'):'<p class="small muted">L’accesso resta disponibile a chi è già nel gruppo</p>'}<div class="actions" style="justify-content:center">${action('Organizza un altro regalo','new-group','secondary')}</div></div></div>`;}
function members(){if(!canManage())return state.role==='participant'?myQuote():access();return `<div class="narrow">${back()}${heading('Partecipanti')}${participantInvitations()}</div>`;}
function privacy(){return `<div class="narrow privacy-page">${back('home','Torna alla home')}${heading('Privacy e dati')}<p>I dati del regalo, le quote e gli indirizzi aggiunti al gruppo restano in questo browser.</p><p>Per accedere con email o Google utilizziamo Firebase Authentication.</p><p>Nome, cognome e scelte sulla privacy e sulle comunicazioni commerciali vengono salvati nel tuo account.</p><p>La scelta sulle comunicazioni commerciali viene registrata nel profilo. Non attiva l’invio di email.</p><p>Gli indirizzi aggiunti al gruppo restano nell’elenco delle persone da invitare.</p><p>Per cancellare i dati del regalo salvati su questo dispositivo, usa le impostazioni del browser.</p></div>`;}
function notFound(){return `<div class="narrow">${heading('Questa pagina non è disponibile')}${button('Torna alla home','home')}</div>`;}
function finder(){return `<div class="narrow finder-page">${back('home','Torna alla home')}<div class="finder-illustration">${giftArt()}</div>${heading('Trova il regalo')}<form id="finder-form"><fieldset><legend>Quali sono i suoi interessi?</legend><div class="interest-options">${[['Tutti','Un po’ di tutto'],...Object.entries(catalogSource.THEMES||{})].map(([v,label])=>`<label class="choice"><input type="radio" name="interest" value="${v}" ${v==='Tutti'?'checked':''}><strong>${label}</strong></label>`).join('')}</div></fieldset>${field('Budget per il regalo (€)','finder-budget','150','number','min="1" max="10000" step="1" required class="short"')}<button class="button" type="submit">Mostra le idee regalo</button></form></div>`;}
function favourites(){const list=products.filter(p=>state.favourites.includes(p.id));return `${heading('I tuoi preferiti')}${list.length?productCards(list):`<div class="empty-state">${icon('heart')}<h2>Quali regali ti piacciono?</h2>${button('Esplora il catalogo','catalog')}</div>`}`;}
function collections(){return `${heading('Le mie collette')}${Object.values(state.scenarios).some(v=>v.published&&authUser&&v.organiserUid===authUser.uid)?'':'<div class="empty-state">'+groupArt()+'<h2>Organizza il primo regalo di gruppo</h2></div>'}<div class="collection-grid">${Object.entries(state.scenarios).filter(([,v])=>v.published&&authUser&&v.organiserUid===authUser.uid).map(([key,v])=>`<article class="collection-card"><div class="collection-art">${v.gift?image(product(v.recipientChoice||v.gift)):groupArt()}</div><div><span class="badge">${v.deliveryAt?'Regalo consegnato':'Adesioni aperte'}</span><h2>Il regalo per ${escape(v.recipient)}</h2><p>${escape(v.occasion)} · ${v.members.length} partecipanti</p><p class="money">${money(v.quota)} a testa</p><button class="button secondary" data-action="open-collection" data-id="${key}">Apri il gruppo</button></div></article>`).join('')}</div><div class="actions">${action('Organizza un regalo di gruppo','new-group')}</div>`;}
function account(){if(!authUser)return access();const privacyDate=authUser.privacyReadAt?new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'long',year:'numeric'}).format(new Date(authUser.privacyReadAt)):null;return `<div class="narrow profile-page">${back('home','Torna alla home')}${heading('Il tuo profilo')}<form id="account-form" class="panel profile-card"><fieldset ${authBusy?'disabled':''}><div class="profile-identity"><span class="profile-avatar" aria-hidden="true">${escape((authUser.nome||'').split(' ').filter(Boolean).map(v=>v[0]).slice(0,2).join(''))}</span><strong>${escape(authUser.nome)}</strong></div><div class="field-pair">${field('Nome','account-first-name',authUser.firstName||authUser.nome||'','text','required maxlength="40" autocomplete="given-name"')}${field('Cognome','account-last-name',authUser.lastName||'','text','maxlength="60" autocomplete="family-name"')}</div>${field('Email','account-email',authUser.email||'','email','readonly autocomplete="email"')}${authUser.provider?`<div class="profile-detail"><span>Metodo di accesso</span><strong>${escape(authUser.provider)}</strong></div>`:''}<div class="profile-detail"><a href="#privacy">Informativa sulla privacy</a><span>${privacyDate?'Letta il '+escape(privacyDate):authUser.privacyVersion?'Presa visione registrata':'Da confermare'}</span></div>${!authUser.privacyVersion?'<label class="consent-row"><input type="checkbox" name="account-privacy" required><span>Ho letto l’<a href="#privacy">informativa sulla privacy</a></span></label>':''}<label class="consent-row profile-marketing"><input type="checkbox" name="account-newsletter" ${authUser.marketing?'checked':''}><span>Voglio ricevere novità e offerte via email <small>Facoltativo</small></span></label><button class="button profile-save" type="submit">Salva modifiche</button></fieldset><p id="profile-progress" class="access-progress" role="status" hidden></p><p id="profile-error" class="access-error" role="alert" hidden></p></form><div class="profile-actions">${action('Organizza un regalo','new-group','secondary')}${action('Esci','sign-out','secondary')}</div></div>`;}
async function saveProfile(form,data){if(authBusy||!authUser)return;authBusy=true;const fieldset=form.querySelector('fieldset');fieldset.disabled=true;form.setAttribute('aria-busy','true');const progress=$('#profile-progress'),error=$('#profile-error');progress.hidden=false;progress.textContent='Salvataggio in corso';error.hidden=true;try{const result=await window.giftyAuth.updateProfile({firstName:String(data.get('account-first-name')||'').trim(),lastName:String(data.get('account-last-name')||'').trim(),privacy:!!authUser.privacyVersion||data.has('account-privacy'),marketing:data.has('account-newsletter'),updateMarketing:profileMarketingDirty});if(!result?.user)throw new Error('profile unavailable');authUser=result.user;profileMarketingDirty=false;authBusy=false;render();toast('Modifiche salvate');}catch{error.textContent='Non siamo riusciti a salvare le modifiche. Riprova';error.hidden=false;}finally{authBusy=false;if(document.contains(form)){fieldset.disabled=false;form.setAttribute('aria-busy','false');progress.hidden=true;}}}

function chrome(page){
 const navPage=['product','alternatives'].includes(page)?'catalog':page;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===navPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.body.dataset.page=page;
 document.body.dataset.recipientSurface=String(state.role==='recipient'&&['recipient','alternatives','product'].includes(page));
 document.querySelectorAll('#mobile-bottom [data-nav]').forEach(a=>{if(!a.querySelector('svg'))a.insertAdjacentHTML('afterbegin',icon(({home:'home',catalog:'grid',finder:'spark',favourites:'heart',collections:'gift'})[a.dataset.nav]));});
 const count=products.filter(p=>state.favourites.includes(p.id)).length;
 document.querySelectorAll('.favourites-count').forEach(el=>{el.textContent=count;el.hidden=!count;});
 $('#account-name-label').textContent=authUser?authUser.nome:'Registrati o accedi';
 $('#account-exit').hidden=!authUser;
 $('#profile-menu').open=false;
 $('#mobile-menu').hidden=true;
 $('#mobile-menu-toggle').setAttribute('aria-expanded','false');
 const hide=['start','setup','access','group','my-quote','members','send','purchase','card','recipient','invite','closed'].includes(page);
 $('#mobile-bottom').hidden=hide||document.body.dataset.recipientSurface==='true';
}

function render(){const route=location.hash.slice(1)||'home';const [page,id]=route.split('/');if($('#scenario'))$('#scenario').value=state.scenario;if($('#role'))$('#role').value=state.role;const screens={home,start,setup,access,share,group,invite,finder,favourites,collections,account,'my-quote':myQuote,catalog:()=>catalog(false),alternatives:()=>catalog(true),product:()=>detail(id),card,send,recipient,purchase,closed,members,privacy};app.innerHTML=(screens[page]||notFound)();chrome(page);if(catalogSource.affiliateDisclosure){let disclosure=document.getElementById('affiliate-disclosure');if(!disclosure){disclosure=document.createElement('p');disclosure.id='affiliate-disclosure';disclosure.className='catalog-note small muted';document.querySelector('.site-footer').append(disclosure);}disclosure.textContent=catalogSource.affiliateDisclosure;}document.title=`Gifty · ${app.querySelector('h1')?.textContent||'Gifty'}`;window.scrollTo(0,0);app.focus({preventScroll:true});}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-go],[data-context]');if(!target)return;if(target.dataset.context){catalogContext=target.dataset.context;state.catalogContext=catalogContext;if(!save()){e.preventDefault();return;}}if(target.dataset.go){go(target.dataset.go);return;}const a=target.dataset.action;if(!a)return;if(a==='google-access'){if(!$('#privacy-consent').reportValidity())return;await submitAccess('google');return;}if(a==='resend-email'){authMode='normal';render();return;}const v=s();if(a==='favourite'){const id=target.dataset.id;if(!product(id))return;const oldScroll=window.scrollY;state.favourites=state.favourites.includes(id)?state.favourites.filter(v=>v!==id):[...state.favourites,id];if(!save())return;render();window.scrollTo(0,oldScroll);document.querySelector(`[data-action="favourite"][data-id="${id}"]`)?.focus({preventScroll:true});return;}if(a==='open-collection'){if(!['A','B'].includes(target.dataset.id)||!authUser||state.scenarios[target.dataset.id].organiserUid!==authUser.uid)return;state.scenario=target.dataset.id;state.role='organiser';if(!save())return;go('group');render();return;}if(a==='reload-catalog'){location.reload();return;}if(a==='more-products'){catalogVisible+=24;renderInPlace();return;}if(a==='clear-filters'||a==='clear-finder'){finderBudget=Infinity;catalogVisible=24;if(a==='clear-filters'){catalogFilter='Tutti';catalogQuery='';catalogRecipient='';catalogAge='';catalogBand='';catalogType='';}render();return;}if(a==='open-share'){if(!mayInvite())return;openShare();return;}if(a==='close-share'){$('#share-dialog').close();return;}if(a==='remove-invitation'){if(!mayInvite())return;v.invitations=pendingInvitations().filter(inv=>inv.id!==target.dataset.id);if(!save())return;renderInPlace('#participant-email');toast('Persona rimossa dalla lista');return;}if(a==='sign-out'){if(authBusy)return;authBusy=true;try{await window.giftyAuth.signOut();authUser=null;authMode='normal';go('home');render();}catch(error){toast(accessError(error));}finally{authBusy=false;}return;}if(a==='new-group'){pendingCatalogGift=null;delete state.catalogDraftGift;if(v.published||v.members.length||pendingInvitations().length){$('#new-group-dialog').showModal();}else{state.newDraft=true;state.role='organiser';if(!save())return;go('start');}return;}if(a==='cancel-new-group'){cancelNewGroup();return;}if(a==='confirm-new-group'){confirmNewGroup();return;}if(a==='signup-participant'){if(v.deliveryAt){go('closed');return;}if(!rememberAuthIntent('participant'))return;if(authUser)applyAuthResult({user:authUser,context:state.authIntent},true);else go('access');}if(a==='decline')toast('Puoi chiudere l’invito senza aderire');if(a==='copy'){try{await navigator.clipboard.writeText(invitationUrl());toast('Link copiato');}catch{const input=$('#share-dialog[open] .link-box input')||$('.link-box input');input.focus();input.select();toast('Seleziona e copia il link');}}if(a==='confirm'){if(!canManage())return;const m=v.members.find(m=>m.id===target.dataset.id);if(m){m.received=m.declaration;if(!save())return;render();toast('Quota ricevuta');}}if(a==='filter'){catalogFilter=target.dataset.value;catalogVisible=24;render();}if(a==='propose'){proposeCatalogGift();return;}if(a==='choose-recipient'||a==='keep'){if(!v.deliveryAt||v.purchasedAt)return;const p=a==='keep'?gift():product(selectedProduct);if(p.price>budget()){toast('Questo regalo supera il budget');return;}v.recipientChoice=p.id;if(!save())return;go('recipient');toast('Scelta salvata');}if(a==='send'){if(!canManage())return;if(!v.deliveryAt&&gift()){v.deliveryAt=new Date().toISOString();if(!save())return;render();toast('Consegna registrata');}}if(a==='delegate'){if(!mayInvite())return;const m=v.members.find(m=>m.id===target.dataset.id);m.invite=!m.invite;if(!save())return;render();toast('Permesso aggiornato');}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(!f.reportValidity())return;const data=new FormData(f),v=s();if(f.id==='account-form'){await saveProfile(f,data);return;}if(f.id==='catalog-search-form'){catalogQuery=data.get('query').trim().slice(0,60);catalogVisible=24;render();return;}if(f.id==='catalog-filters-form'){catalogRecipient=data.get('catalog-recipient');catalogAge=data.get('catalog-age');catalogBand=data.get('catalog-band');catalogType=data.get('catalog-type');catalogVisible=24;render();return;}if(f.id==='finder-form'){catalogVisible=24;catalogRecipient='';catalogAge='';catalogBand='';catalogType='';catalogFilter=data.get('interest');finderBudget=Math.round(Number(data.get('finder-budget'))*100);catalogQuery='';catalogContext='organiser';state.catalogContext=catalogContext;if(!save())return;go('catalog');return;}if(f.id==='invitation-form'){if(!mayInvite()){toast('Le adesioni sono chiuse');return;}const email=String(data.get('participant-email')||'').trim().toLowerCase(),name=String(data.get('participant-name')||'').trim();const input=$('#participant-email');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){input.setCustomValidity('Scrivi un indirizzo email valido');input.reportValidity();return;}if(pendingInvitations().some(inv=>inv.email.toLowerCase()===email)||v.members.some(m=>m.email?.toLowerCase()===email)){input.setCustomValidity('Questa email è già nella lista');input.reportValidity();return;}v.invitations=[...pendingInvitations(),{id:crypto.randomUUID(),email,name}];if(!save())return;renderInPlace('#participant-email');toast('Persona aggiunta alla lista');return;}if(f.id==='start-form'){if(!state.newDraft&&!mayEditDraft())return;const oldRecipient=v.recipient;v.recipient=data.get('recipient').trim();if(v.cardMessage===`Buon compleanno, ${oldRecipient}! Per tutte le avventure che ci aspettano`)v.cardMessage=`Buon compleanno, ${v.recipient}! Per tutte le avventure che ci aspettano`;if(!v.recipient){$('#recipient').setCustomValidity('Scrivi il nome di chi festeggiamo');$('#recipient').reportValidity();return;}v.occasion=data.get('occasion');v.date=data.get('date');v.mode=data.get('mode');if(state.newDraft){if(state.catalogDraftGift){v.gift=v.mode==='B'&&product(state.catalogDraftGift)?.url?state.catalogDraftGift:null;v.expected=v.mode==='B'?10:8;v.quota=1000;delete state.catalogDraftGift;delete state.authIntent;}v.organiserUid=null;v.organiserName='';v.organiserAccount=false;v.draftId=crypto.randomUUID();v.published=false;v.members=[];v.invitations=[];v.joined=false;v.participantAccount=false;v.deliveryAt=null;v.recipientChoice=null;v.purchasedAt=null;v.actualCost=null;v.dedication='';state.newDraft=false;}if(v.mode==='A'&&!v.published)v.gift=null;if(!save())return;catalogContext='organiser';state.catalogContext=catalogContext;if(!save())return;go(v.mode==='B'&&!v.gift?'catalog':'setup');}if(f.id==='setup-form'){if(!mayEditDraft())return;v.expected=Number(data.get('expected'));v.quota=v.mode==='A'?Math.round(Number(data.get('quota'))*100):Math.ceil((gift()?.price||15000)/v.expected);if(!rememberAuthIntent('organiser'))return;if(authUser)applyAuthResult({user:authUser,context:state.authIntent},true);else go('access');return;}if(f.id==='access-form'){await submitAccess(authMode==='needs-email'?'complete':authMode==='needs-consent'?'profile':'email');return;}if(f.id==='quota-form'){if(!canManage())return;v.quota=Math.round(Number(data.get('quota'))*100);quotaEditing=false;if(!save())return;renderInPlace('#quota');toast('Quota aggiornata');}if(f.id==='payment-form'){const m=member();if(!m)return;m.declaration=m.received+Math.round(Number(data.get('amount'))*100);if(!save())return;render();toast('Pagamento dichiarato');}if(f.id==='card-form'){if(v.deliveryAt||!(canManage()||state.role==='participant'&&member()))return;if(state.role==='participant')v.dedication=data.get('message').trim();else v.cardMessage=data.get('message').trim();if(!save())return;render();$('#message')?.focus({preventScroll:true});toast('Modifiche salvate');}if(f.id==='purchase-form'){if(!canManage())return;v.purchasedAt=new Date().toISOString();v.actualCost=Math.round(Number(data.get('actualCost'))*100);if(v.mode==='B'&&v.members.length)v.quota=Math.ceil(v.actualCost/v.members.length);if(!save())return;render();toast('Acquisto registrato');}});
document.addEventListener('input',e=>{if(['recipient','participant-email'].includes(e.target.id))e.target.setCustomValidity('');if(e.target.form?.id==='setup-form'){const form=e.target.form;const expected=Number(form.elements.expected.value)||1;const cents=s().mode==='A'?Math.round(Number(form.elements.quota.value||0)*100)*expected:Math.ceil((gift()?.price||15000)/expected);$('#estimate').textContent=money(cents);$('#estimate-note').textContent=s().mode==='A'?`in ${expected} partecipanti`:`a testa in ${expected}`;}});
document.addEventListener('change',e=>{if(e.target.name==='newsletter'&&e.target.form?.id==='access-form')authMarketingDirty=true;if(e.target.name==='account-newsletter'&&e.target.form?.id==='account-form')profileMarketingDirty=true;if(e.target.name==='paymentMethod'){paymentMethod=e.target.value;$('#method-detail').textContent=methodDetail();}});
$('#mobile-menu-toggle').addEventListener('click',()=>{const hidden=!$('#mobile-menu').hidden;$('#mobile-menu').hidden=hidden;$('#mobile-menu-toggle').setAttribute('aria-expanded',String(!hidden));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#profile-menu').open){$('#profile-menu').open=false;$('#profile-menu summary').focus();}if(!$('#mobile-menu').hidden){$('#mobile-menu').hidden=true;$('#mobile-menu-toggle').setAttribute('aria-expanded','false');$('#mobile-menu-toggle').focus();}}});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#profile-menu'))$('#profile-menu').open=false;});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();app.focus();app.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',render);
window.addEventListener('storage',e=>{if(e.key===KEY){try{const incoming=JSON.parse(e.newValue);if(!validState(incoming)){toast('I dati dell’altra scheda non sono compatibili');return;}state=incoming;Object.values(state.scenarios).forEach(v=>{v.invitations=Array.isArray(v.invitations)?v.invitations:[];v.draftId=typeof v.draftId==='string'?v.draftId:crypto.randomUUID();});state.favourites=Array.isArray(state.favourites)?state.favourites.filter(id=>validSavedProductId(id)):[];lastGood=JSON.stringify(state);accessContext=state.accessContext||'organiser';catalogContext=state.catalogContext||(state.role==='recipient'?'recipient':'organiser');render();}catch{}}});
$('#share-dialog').addEventListener('click',event=>{if(event.target===$('#share-dialog'))$('#share-dialog').close();});
render();
initialiseAuth();
})();
